# GENERATED by build.ps1 from apps.json + src/engine.ps1 - edit those, not this file.
# App: ShareX (sharex)

# Kura elevates before launching scripts, so there is no self-elevation here.
# Outside Kura, run from an elevated PowerShell.

<#
.SYNOPSIS
    Installs the latest version of common apps straight from the vendor, for machines
    without the Microsoft Store or winget.

.DESCRIPTION
    This is the shared engine. build.ps1 copies it into every script in scripts\ and
    embeds the app definitions from apps.json:
      scripts\install-<id>.ps1  - one app: shows installed vs latest, then asks
      scripts\install-apps.ps1  - every app, as a pick-from-a-list menu

    Single-app script:
      - already on the latest version -> reinstall (silent / interactive) or cancel
      - older or not installed         -> install silently, interactively, or cancel
      -Unattended installs/updates silently with no prompts (PDQ, RMM, scheduled task).

    Interactive (default): shows a menu with installed vs. latest versions. For each app
    you pick:
      - already on the latest version -> reinstall (silent / interactive) or cancel
      - older or not installed         -> install silently, interactively, or cancel

    Unattended (-App): no prompts. Good for PDQ Deploy, RMM tools, or scheduled tasks.

.PARAMETER Manifest
    Path or http(s) URL to an apps.json to use instead of the embedded app list.

.PARAMETER Unattended
    Single-app scripts only. Install/update this app with no prompts; skips it if it's
    already current (add -Force to reinstall). Same as -App <id>.

.PARAMETER App
    Unattended mode. App ids to install (see -List), or 'all' / 'updates'.

.PARAMETER Mode
    Unattended mode only. Silent (default) or Interactive.

.PARAMETER Force
    Unattended mode only. Reinstall even if the app is already on the latest version.

.PARAMETER CheckFeeds
    Resolve the latest version + download URL for every app, check each download
    URL answers, print the results and exit (1 if any failed). Installs nothing.
    Used by the repo's scheduled CI job to catch vendors changing their links.

.PARAMETER List
    Print the app table (installed vs latest) and exit.

.PARAMETER SkipSignatureCheck
    Don't require a valid Authenticode signature on downloaded installers.

.EXAMPLE
    .\install-chrome.ps1
    Shows Chrome's installed vs latest version and asks what to do.

.EXAMPLE
    .\install-chrome.ps1 -Unattended
    Silently installs/updates Chrome; does nothing if it's already current.

.EXAMPLE
    .\install-apps.ps1 -App updates
    Silently updates every app that is installed and out of date.
#>
[CmdletBinding()]
param(
    [string]$Manifest,
    [string[]]$App,
    [ValidateSet('Silent', 'Interactive')]
    [string]$Mode = 'Silent',
    [switch]$Force,
    [switch]$List,
    [switch]$CheckFeeds,
    [switch]$Unattended,
    [switch]$SkipSignatureCheck,
    [string]$DownloadPath = (Join-Path ([IO.Path]::GetTempPath()) 'KuraApps'),
    [switch]$KeepDownloads
)

